/** Projects a lat/lon to the map's SVG coordinates. */
export function project(lat: number, lon: number): [number, number] {
	const my = Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360)) * (180 / Math.PI);
	return [(lon - 78.289175) * 140.49508373854383 + 500, -(my - 10.883216853771053) * 140.49508373854383 + 540];
}

